if (StringUtils::IsNaturalNumber(strWindow))
{
  // Allow a full window ID or a delta ID
  int iWindow = atoi(strWindow.c_str());
  if (iWindow > WINDOW_INVALID)
    return iWindow;

  return WINDOW_HOME + iWindow;
}

